// KeywordChipsInput — a chip/pill text input for editing a list of keywords.
//
// Typing text and pressing Enter or comma commits a trimmed, non-empty,
// non-duplicate chip. Each chip is a removable pill carrying a real
// <button aria-label="Remove <kw>">. Backspace on an empty input removes the
// last chip. An aria-live="polite" region announces additions/removals.
//
// All mutations return a NEW array via onChange — the component never mutates
// the incoming value array (immutability).
//
// cog- token visual language matches the rest of dialogue-mfe (pill chips,
// 44px input, focus ring). The dynamic `label` + `help` text are
// caller-supplied (server-provided field label or an i18n string) so this
// component carries no raw literals.

import { type ReactElement, useId, useState } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { X } from "@omnicore-platform/ui/icons";

interface Props {
  readonly value: ReadonlyArray<string>;
  readonly onChange: (next: string[]) => void;
  readonly label: string;
  readonly help?: string;
}

export function KeywordChipsInput({
  value,
  onChange,
  label,
  help,
}: Props): ReactElement {
  const [draft, setDraft] = useState("");
  const [announcement, setAnnouncement] = useState("");
  const inputId = useId();
  const helpId = useId();

  const commit = (raw: string): void => {
    const keyword = raw.trim();
    setDraft("");
    if (keyword === "" || value.includes(keyword)) return;
    onChange([...value, keyword]);
    setAnnouncement(`${m.recipes_keyword_add_hint()} ${keyword}`);
  };

  const removeAt = (index: number): void => {
    const removed = value[index];
    onChange(value.filter((_, i) => i !== index));
    setAnnouncement(`${m.recipes_keyword_remove()} ${removed}`);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>): void => {
    if (e.key === "Enter" || e.key === ",") {
      e.preventDefault();
      commit(draft);
      return;
    }
    if (e.key === "Backspace" && draft === "" && value.length > 0) {
      e.preventDefault();
      removeAt(value.length - 1);
    }
  };

  return (
    <div className="flex flex-col gap-cog-1">
      <label
        htmlFor={inputId}
        className="text-body-sm font-semibold text-cog-text-primary"
      >
        {label}
      </label>

      <div className="flex flex-wrap items-center gap-cog-1 rounded-lg border border-cog-border bg-cog-surface px-cog-2 py-cog-1 focus-within:border-cog-blue-600 focus-within:ring-2 focus-within:ring-cog-focus">
        {value.map((keyword, index) => (
          <span
            key={keyword}
            className="inline-flex items-center gap-cog-0-5 rounded-pill border border-cog-border bg-cog-surface-subtle px-cog-2 py-cog-0-5 text-caption text-cog-text-secondary"
          >
            {keyword}
            <button
              type="button"
              onClick={() => removeAt(index)}
              aria-label={`${m.recipes_keyword_remove()} ${keyword}`}
              className="ms-cog-0-5 flex min-h-cog-5 min-w-cog-5 items-center justify-center rounded-sm text-cog-text-tertiary hover:text-cog-danger-500 focus:outline-none focus:ring-2 focus:ring-cog-focus"
            >
              <X aria-hidden="true" className="h-cog-3-5 w-cog-3-5" />
            </button>
          </span>
        ))}

        <input
          id={inputId}
          type="text"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={handleKeyDown}
          aria-label={label}
          aria-describedby={help ? helpId : undefined}
          className="min-w-cog-measure-sm flex-1 bg-transparent py-cog-1 text-body-sm text-cog-text-primary placeholder:text-cog-text-tertiary focus:outline-none"
          placeholder={m.recipes_keyword_add_hint()}
        />
      </div>

      {help && (
        <p id={helpId} className="text-caption text-cog-text-tertiary">
          {help}
        </p>
      )}

      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}


