// RecipeWizard — the schema-driven recipe-create/edit step machine.
//
// Four steps: trigger → action → constraints → review. This task (2b-T5)
// implements the step indicator + the Trigger and Action steps; constraints
// and review are minimal placeholders that Task 6 fills in (submit/test live
// there too).
//
// On mount the wizard loads the trigger + action introspection metadata and
// the contact-group + channel option lists (reused by SchemaFields' uuid
// selects). It shows a loading state until all four resolve and an error
// state if any of them fails.
//
// State is held in a useReducer so step navigation never loses prior input
// (Back from Action returns to Trigger with the keyword list intact).
//
// All user-facing copy comes from m.recipes_*(); the per-trigger/action label
// and description are server-provided (no raw JSX literals here).

import {
  type ReactElement,
  useEffect,
  useId,
  useReducer,
  useRef,
  useState,
} from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { cn } from "@omnicore-platform/ui";
import { Check, X } from "@omnicore-platform/ui/icons";
import {
  listTriggerTypes,
  listActionTypes,
  createRecipe,
  updateRecipe,
  testRecipeDraft,
  type Recipe,
  type TriggerTypeInfo,
  type ActionTypeInfo,
  type ConfigField,
  type CreateRecipeRequest,
  type UpdateRecipeRequest,
  type TestRecipeResponse,
} from "../../api/recipes";
import { listContactGroups } from "../../api/contactGroups";
import { listChannels } from "../../api/channels";
import { defaultConfigFor, requiredFieldsMissing } from "../../recipes/schema";
import { SchemaFields } from "./SchemaFields";

// ─── Types ─────────────────────────────────────────────────────────────────

type WizardStep = "trigger" | "action" | "constraints" | "review";

const STEP_ORDER: ReadonlyArray<WizardStep> = [
  "trigger",
  "action",
  "constraints",
  "review",
];

interface Option {
  readonly id: string;
  readonly name: string;
  /** Present on channel options only — the wire channel-type enum string. */
  readonly type?: string;
}

interface Props {
  readonly mode: "create" | "edit";
  readonly initial?: Recipe;
  readonly onDone: (recipeId: string) => void;
  readonly onCancel: () => void;
}

type LoadState =
  | { tag: "loading" }
  | {
      tag: "ready";
      triggers: ReadonlyArray<TriggerTypeInfo>;
      actions: ReadonlyArray<ActionTypeInfo>;
      groups: ReadonlyArray<Option>;
      channels: ReadonlyArray<Option>;
    }
  | { tag: "error" };

// ─── Wizard reducer ──────────────────────────────────────────────────────────

interface WizardState {
  readonly step: WizardStep;
  readonly name: string;
  readonly description: string;
  readonly triggerType: string;
  readonly triggerConfig: Record<string, unknown>;
  readonly actionType: string;
  readonly actionConfig: Record<string, unknown>;
  readonly channelId: string;
  readonly channelType: string;
  readonly cooldownMinutes: number;
  readonly maxPerContact: number;
}

type WizardAction =
  | { kind: "goto"; step: WizardStep }
  | {
      kind: "selectTrigger";
      triggerType: string;
      triggerConfig: Record<string, unknown>;
    }
  | { kind: "setTriggerConfig"; name: string; value: unknown }
  | {
      kind: "selectAction";
      actionType: string;
      actionConfig: Record<string, unknown>;
    }
  | { kind: "setActionConfig"; name: string; value: unknown }
  | { kind: "setName"; value: string }
  | { kind: "setDescription"; value: string }
  | { kind: "setChannel"; channelId: string; channelType: string }
  | { kind: "setCooldown"; value: number }
  | { kind: "setMaxPerContact"; value: number };

function wizardReducer(state: WizardState, action: WizardAction): WizardState {
  switch (action.kind) {
    case "goto":
      return { ...state, step: action.step };
    case "selectTrigger":
      return {
        ...state,
        triggerType: action.triggerType,
        triggerConfig: action.triggerConfig,
      };
    case "setTriggerConfig":
      return {
        ...state,
        triggerConfig: {
          ...state.triggerConfig,
          [action.name]: action.value,
        },
      };
    case "selectAction":
      return {
        ...state,
        actionType: action.actionType,
        actionConfig: action.actionConfig,
      };
    case "setActionConfig":
      return {
        ...state,
        actionConfig: {
          ...state.actionConfig,
          [action.name]: action.value,
        },
      };
    case "setName":
      return { ...state, name: action.value };
    case "setDescription":
      return { ...state, description: action.value };
    case "setChannel":
      return {
        ...state,
        channelId: action.channelId,
        channelType: action.channelType,
      };
    case "setCooldown":
      return { ...state, cooldownMinutes: action.value };
    case "setMaxPerContact":
      return { ...state, maxPerContact: action.value };
    default:
      return state;
  }
}

function initialWizardState(initial?: Recipe): WizardState {
  return {
    step: "trigger",
    name: initial?.name ?? "",
    description: initial?.description ?? "",
    triggerType: initial?.trigger_type ?? "",
    triggerConfig: initial?.trigger_config ?? {},
    actionType: initial?.action_type ?? "",
    actionConfig: initial?.action_config ?? {},
    channelId: initial?.channel_id ?? "",
    channelType: initial?.channel_type ?? "",
    cooldownMinutes: initial?.cooldown_minutes ?? 0,
    maxPerContact: initial?.max_executions_per_contact ?? 0,
  };
}

// ─── Component ────────────────────────────────────────────────────────────────

export function RecipeWizard({
  mode,
  initial,
  onDone,
  onCancel,
}: Props): ReactElement {
  const [load, setLoad] = useReducer(
    (_prev: LoadState, next: LoadState) => next,
    { tag: "loading" } as LoadState,
  );
  const [state, dispatch] = useReducer(
    wizardReducer,
    initial,
    initialWizardState,
  );
  const headingRef = useRef<HTMLHeadingElement | null>(null);

  // Name validation surfaced inline on the Constraints step.
  const [nameError, setNameError] = useState(false);
  // Submit + test lifecycle.
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<TestRecipeResponse | null>(null);
  const [testError, setTestError] = useState(false);

  // On mount, load introspection metadata + option lists. Each list failure
  // collapses the whole wizard to the error state — the wizard cannot operate
  // without the trigger/action schemas.
  useEffect(() => {
    let cancelled = false;
    void Promise.all([
      listTriggerTypes(),
      listActionTypes(),
      listContactGroups(),
      listChannels(),
    ])
      .then(([triggers, actions, groupsResp, channelsResp]) => {
        if (cancelled) return;
        const groups: ReadonlyArray<Option> = (groupsResp.groups ?? []).map(
          (g) => ({ id: g.id, name: g.name }),
        );
        const channels: ReadonlyArray<Option> = (
          channelsResp.channels ?? []
        ).map((c) => ({ id: c.id, name: c.name, type: c.type }));
        setLoad({ tag: "ready", triggers, actions, groups, channels });
      })
      .catch(() => {
        if (!cancelled) setLoad({ tag: "error" });
      });
    return () => {
      cancelled = true;
    };
  }, []);

  // On step change, move focus to the step heading for screen-reader flow.
  useEffect(() => {
    headingRef.current?.focus();
  }, [state.step]);

  if (load.tag === "loading") {
    return (
      <div
        className="flex items-center justify-center py-cog-8 text-body-sm text-cog-text-secondary"
        role="status"
      >
        {m.recipes_loading()}
      </div>
    );
  }

  if (load.tag === "error") {
    return (
      <div
        role="alert"
        className="rounded-md border border-cog-danger-300 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-dark-border dark:bg-cog-danger-dark-bg dark:text-cog-danger-dark"
      >
        {m.recipes_load_error()}
      </div>
    );
  }

  const { triggers, actions, groups, channels } = load;
  const selectedTrigger = triggers.find((t) => t.key === state.triggerType);
  const selectedAction = actions.find((a) => a.key === state.actionType);
  const supportedActions = actions.filter((a) => a.supported);
  const unsupportedActions = actions.filter((a) => !a.supported);

  // Whether the current step's required fields are all satisfied (gates
  // Continue). Constraints/review are placeholders so they always advance.
  function canContinue(): boolean {
    if (state.step === "trigger") {
      if (!selectedTrigger) return false;
      return (
        requiredFieldsMissing(
          selectedTrigger.config_schema.fields,
          state.triggerConfig,
        ).length === 0
      );
    }
    if (state.step === "action") {
      if (!selectedAction) return false;
      return (
        requiredFieldsMissing(
          selectedAction.config_schema.fields,
          state.actionConfig,
        ).length === 0
      );
    }
    return true;
  }

  function goToStep(step: WizardStep): void {
    dispatch({ kind: "goto", step });
  }

  function handleContinue(): void {
    // The Constraints step gates on a non-empty name (inline alert on miss).
    if (state.step === "constraints") {
      if (state.name.trim() === "") {
        setNameError(true);
        return;
      }
      setNameError(false);
    }
    if (!canContinue()) return;
    const idx = STEP_ORDER.indexOf(state.step);
    const next = STEP_ORDER[idx + 1];
    if (next) goToStep(next);
  }

  // Assemble the create request from the current wizard state.
  function buildCreateRequest(): CreateRecipeRequest {
    return {
      name: state.name.trim(),
      description: state.description,
      trigger_type: state.triggerType,
      trigger_config: state.triggerConfig,
      action_type: state.actionType,
      action_config: state.actionConfig,
      channel_id: state.channelId,
      channel_type: state.channelType,
      max_executions_per_contact: state.maxPerContact,
      cooldown_minutes: state.cooldownMinutes,
    };
  }

  // Edit mode sends only the editable fields (no trigger_type/action_type — the
  // recipe's type is immutable once created).
  function buildUpdateRequest(): UpdateRecipeRequest {
    return {
      name: state.name.trim(),
      description: state.description,
      trigger_config: state.triggerConfig,
      action_config: state.actionConfig,
      channel_id: state.channelId,
      channel_type: state.channelType,
      max_executions_per_contact: state.maxPerContact,
      cooldown_minutes: state.cooldownMinutes,
    };
  }

  async function handleSave(): Promise<void> {
    setSaving(true);
    setSaveError(false);
    try {
      const recipe =
        mode === "edit" && initial
          ? await updateRecipe(initial.id, buildUpdateRequest())
          : await createRecipe(buildCreateRequest());
      onDone(recipe.id);
    } catch {
      setSaveError(true);
    } finally {
      setSaving(false);
    }
  }

  async function handleTest(sampleTriggerData: Record<string, unknown>): Promise<void> {
    setTesting(true);
    setTestError(false);
    setTestResult(null);
    try {
      const result = await testRecipeDraft({
        trigger_type: state.triggerType,
        trigger_config: state.triggerConfig,
        action_type: state.actionType,
        action_config: state.actionConfig,
        sample_trigger_data: sampleTriggerData,
      });
      setTestResult(result);
    } catch {
      setTestError(true);
    } finally {
      setTesting(false);
    }
  }

  function handleBack(): void {
    const idx = STEP_ORDER.indexOf(state.step);
    const prev = STEP_ORDER[idx - 1];
    if (prev) goToStep(prev);
  }

  function selectTrigger(trigger: TriggerTypeInfo): void {
    dispatch({
      kind: "selectTrigger",
      triggerType: trigger.key,
      triggerConfig: defaultConfigFor(trigger.config_schema.fields),
    });
  }

  function selectAction(action: ActionTypeInfo): void {
    dispatch({
      kind: "selectAction",
      actionType: action.key,
      actionConfig: defaultConfigFor(action.config_schema.fields),
    });
  }

  const isFirstStep = STEP_ORDER.indexOf(state.step) === 0;
  const showContinue =
    state.step === "trigger" ||
    state.step === "action" ||
    state.step === "constraints";
  const showSave = state.step === "review";

  return (
    <div className="flex flex-col gap-cog-6">
      <StepIndicator activeStep={state.step} onJump={goToStep} />

      <div>
        {state.step === "trigger" && (
          <TriggerStep
            headingRef={headingRef}
            triggers={triggers}
            selectedTrigger={selectedTrigger}
            triggerConfig={state.triggerConfig}
            groups={groups}
            channels={channels}
            onSelect={selectTrigger}
            onConfigChange={(name, value) =>
              dispatch({ kind: "setTriggerConfig", name, value })
            }
          />
        )}
        {state.step === "action" && (
          <ActionStep
            headingRef={headingRef}
            supportedActions={supportedActions}
            unsupportedActions={unsupportedActions}
            selectedAction={selectedAction}
            actionConfig={state.actionConfig}
            groups={groups}
            channels={channels}
            onSelect={selectAction}
            onConfigChange={(name, value) =>
              dispatch({ kind: "setActionConfig", name, value })
            }
          />
        )}
        {state.step === "constraints" && (
          <ConstraintsStep
            headingRef={headingRef}
            name={state.name}
            description={state.description}
            channelId={state.channelId}
            cooldownMinutes={state.cooldownMinutes}
            maxPerContact={state.maxPerContact}
            channels={channels}
            nameError={nameError}
            onName={(value) => {
              if (value.trim() !== "") setNameError(false);
              dispatch({ kind: "setName", value });
            }}
            onDescription={(value) =>
              dispatch({ kind: "setDescription", value })
            }
            onChannel={(channelId, channelType) =>
              dispatch({ kind: "setChannel", channelId, channelType })
            }
            onCooldown={(value) => dispatch({ kind: "setCooldown", value })}
            onMaxPerContact={(value) =>
              dispatch({ kind: "setMaxPerContact", value })
            }
          />
        )}
        {state.step === "review" && (
          <ReviewStep
            headingRef={headingRef}
            state={state}
            selectedTrigger={selectedTrigger}
            selectedAction={selectedAction}
            channels={channels}
            groups={groups}
            testing={testing}
            testResult={testResult}
            testError={testError}
            saveError={saveError}
            onTest={(sample) => void handleTest(sample)}
          />
        )}
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between border-t border-cog-border pt-cog-4">
        <div className="flex items-center gap-cog-3">
          <button
            type="button"
            onClick={onCancel}
            className="inline-flex min-h-btn items-center justify-center rounded-md border border-cog-border px-cog-4 py-cog-2 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-subtle focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2"
          >
            {m.recipes_cancel()}
          </button>
          {!isFirstStep && (
            <button
              type="button"
              onClick={handleBack}
              className="inline-flex min-h-btn items-center justify-center rounded-md border border-cog-border px-cog-4 py-cog-2 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-subtle focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2"
            >
              {m.recipes_back()}
            </button>
          )}
        </div>
        {showContinue && (
          <button
            type="button"
            onClick={handleContinue}
            disabled={!canContinue()}
            className="inline-flex min-h-btn items-center justify-center rounded-md bg-cog-blue-600 px-cog-4 py-cog-2 text-body-sm font-semibold text-white hover:bg-cog-blue-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:bg-cog-border disabled:text-cog-text-tertiary"
          >
            {m.recipes_continue()}
          </button>
        )}
        {showSave && (
          <button
            type="button"
            onClick={() => void handleSave()}
            disabled={saving}
            className="inline-flex min-h-btn items-center justify-center rounded-md bg-cog-blue-600 px-cog-4 py-cog-2 text-body-sm font-semibold text-white hover:bg-cog-blue-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:bg-cog-border disabled:text-cog-text-tertiary"
          >
            {saving ? m.recipes_saving() : m.recipes_save()}
          </button>
        )}
      </div>
    </div>
  );
}

// ─── Step indicator ────────────────────────────────────────────────────────────

function stepLabel(step: WizardStep): string {
  switch (step) {
    case "trigger":
      return m.recipes_step_trigger();
    case "action":
      return m.recipes_step_action();
    case "constraints":
      return m.recipes_step_constraints();
    case "review":
      return m.recipes_step_review();
  }
}

function StepIndicator({
  activeStep,
  onJump,
}: {
  readonly activeStep: WizardStep;
  readonly onJump: (step: WizardStep) => void;
}): ReactElement {
  const activeIdx = STEP_ORDER.indexOf(activeStep);
  return (
    <ol className="flex items-center gap-cog-2">
      {STEP_ORDER.map((step, idx) => {
        const isCompleted = idx < activeIdx;
        const isActive = idx === activeIdx;
        const isReached = idx <= activeIdx;
        const label = stepLabel(step);

        const pillClasses = cn(
          "inline-flex items-center gap-cog-2 rounded-pill px-cog-3 py-cog-1.5 text-body-sm font-medium",
          isActive
            ? "border border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:bg-cog-blue-900/20 dark:text-cog-blue-300"
            : isCompleted
              ? "border border-cog-border bg-cog-surface text-cog-text-primary"
              : "border border-cog-border bg-cog-surface-subtle text-cog-text-tertiary",
        );

        const badge = (
          <>
            <span
              aria-hidden="true"
              className={cn(
                "inline-flex h-cog-4-5 w-cog-4-5 items-center justify-center rounded-pill text-caption font-semibold",
                isActive
                  ? "bg-cog-blue-600 text-white"
                  : isCompleted
                    ? "bg-cog-green-600 text-white"
                    : "bg-cog-border text-cog-text-tertiary",
              )}
            >
              {isCompleted ? (
                <Check aria-hidden="true" className="h-cog-3-5 w-cog-3-5" />
              ) : (
                String(idx + 1)
              )}
            </span>
            {label}
          </>
        );

        return (
          <li key={step}>
            {isCompleted ? (
              <button
                type="button"
                onClick={() => onJump(step)}
                className={cn(pillClasses, "hover:bg-cog-surface-subtle focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus")}
              >
                {badge}
              </button>
            ) : (
              <span
                className={pillClasses}
                aria-current={isActive ? "step" : undefined}
                aria-disabled={!isReached ? "true" : undefined}
              >
                {badge}
              </span>
            )}
          </li>
        );
      })}
    </ol>
  );
}

// ─── Selectable card ───────────────────────────────────────────────────────────

function SelectableCard({
  title,
  description,
  selected,
  onSelect,
}: {
  readonly title: string;
  readonly description: string;
  readonly selected: boolean;
  readonly onSelect: () => void;
}): ReactElement {
  return (
    <button
      type="button"
      onClick={onSelect}
      aria-pressed={selected}
      className={cn(
        "flex flex-col gap-cog-1 rounded-lg border p-cog-4 text-start focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus",
        selected
          ? "border-cog-blue-600 bg-cog-blue-50 dark:bg-cog-blue-900/20"
          : "border-cog-border bg-cog-surface hover:bg-cog-surface-subtle",
      )}
    >
      <span className="text-body-sm font-semibold text-cog-text-primary">
        {title}
      </span>
      <span className="text-caption text-cog-text-secondary">{description}</span>
    </button>
  );
}

function DisabledCard({
  title,
  description,
}: {
  readonly title: string;
  readonly description: string;
}): ReactElement {
  return (
    <div
      aria-disabled="true"
      tabIndex={-1}
      className="flex cursor-not-allowed flex-col gap-cog-1 rounded-lg border border-cog-border bg-cog-surface-subtle p-cog-4 text-start opacity-60"
    >
      <span className="text-body-sm font-semibold text-cog-text-tertiary">
        {title}
      </span>
      <span className="text-caption text-cog-text-tertiary">{description}</span>
    </div>
  );
}

// ─── Trigger step ──────────────────────────────────────────────────────────────

function TriggerStep({
  headingRef,
  triggers,
  selectedTrigger,
  triggerConfig,
  groups,
  channels,
  onSelect,
  onConfigChange,
}: {
  readonly headingRef: React.RefObject<HTMLHeadingElement>;
  readonly triggers: ReadonlyArray<TriggerTypeInfo>;
  readonly selectedTrigger: TriggerTypeInfo | undefined;
  readonly triggerConfig: Record<string, unknown>;
  readonly groups: ReadonlyArray<Option>;
  readonly channels: ReadonlyArray<Option>;
  readonly onSelect: (trigger: TriggerTypeInfo) => void;
  readonly onConfigChange: (name: string, val: unknown) => void;
}): ReactElement {
  return (
    <section className="flex flex-col gap-cog-4">
      <h2
        ref={headingRef}
        tabIndex={-1}
        className="text-heading-sm font-semibold text-cog-text-primary focus:outline-none"
      >
        {m.recipes_when_prompt()}
      </h2>
      <div className="grid grid-cols-1 gap-cog-3 sm:grid-cols-2">
        {triggers.map((trigger) => (
          <SelectableCard
            key={trigger.key}
            title={trigger.label}
            description={trigger.description}
            selected={selectedTrigger?.key === trigger.key}
            onSelect={() => onSelect(trigger)}
          />
        ))}
      </div>
      {selectedTrigger && selectedTrigger.config_schema.fields.length > 0 && (
        <SchemaFields
          fields={selectedTrigger.config_schema.fields}
          value={triggerConfig}
          onChange={onConfigChange}
          groups={groups}
          channels={channels}
        />
      )}
    </section>
  );
}

// ─── Action step ───────────────────────────────────────────────────────────────

function ActionStep({
  headingRef,
  supportedActions,
  unsupportedActions,
  selectedAction,
  actionConfig,
  groups,
  channels,
  onSelect,
  onConfigChange,
}: {
  readonly headingRef: React.RefObject<HTMLHeadingElement>;
  readonly supportedActions: ReadonlyArray<ActionTypeInfo>;
  readonly unsupportedActions: ReadonlyArray<ActionTypeInfo>;
  readonly selectedAction: ActionTypeInfo | undefined;
  readonly actionConfig: Record<string, unknown>;
  readonly groups: ReadonlyArray<Option>;
  readonly channels: ReadonlyArray<Option>;
  readonly onSelect: (action: ActionTypeInfo) => void;
  readonly onConfigChange: (name: string, val: unknown) => void;
}): ReactElement {
  return (
    <section className="flex flex-col gap-cog-4">
      <h2
        ref={headingRef}
        tabIndex={-1}
        className="text-heading-sm font-semibold text-cog-text-primary focus:outline-none"
      >
        {m.recipes_then_prompt()}
      </h2>
      <div className="grid grid-cols-1 gap-cog-3 sm:grid-cols-2">
        {supportedActions.map((action) => (
          <SelectableCard
            key={action.key}
            title={action.label}
            description={action.description}
            selected={selectedAction?.key === action.key}
            onSelect={() => onSelect(action)}
          />
        ))}
      </div>

      {selectedAction && selectedAction.config_schema.fields.length > 0 && (
        <SchemaFields
          fields={selectedAction.config_schema.fields}
          value={actionConfig}
          onChange={onConfigChange}
          groups={groups}
          channels={channels}
        />
      )}

      {unsupportedActions.length > 0 && (
        <div className="flex flex-col gap-cog-2 border-t border-cog-border pt-cog-4">
          <h3 className="text-body-sm font-semibold text-cog-text-secondary">
            {m.recipes_coming_soon()}
          </h3>
          <p className="text-caption text-cog-text-tertiary">
            {m.recipes_action_unsupported_hint()}
          </p>
          <div className="grid grid-cols-1 gap-cog-3 sm:grid-cols-2">
            {unsupportedActions.map((action) => (
              <DisabledCard
                key={action.key}
                title={action.label}
                description={action.description}
              />
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

// ─── Constraints step ────────────────────────────────────────────────────────

function ConstraintsStep({
  headingRef,
  name,
  description,
  channelId,
  cooldownMinutes,
  maxPerContact,
  channels,
  nameError,
  onName,
  onDescription,
  onChannel,
  onCooldown,
  onMaxPerContact,
}: {
  readonly headingRef: React.RefObject<HTMLHeadingElement>;
  readonly name: string;
  readonly description: string;
  readonly channelId: string;
  readonly cooldownMinutes: number;
  readonly maxPerContact: number;
  readonly channels: ReadonlyArray<Option>;
  readonly nameError: boolean;
  readonly onName: (value: string) => void;
  readonly onDescription: (value: string) => void;
  readonly onChannel: (channelId: string, channelType: string) => void;
  readonly onCooldown: (value: number) => void;
  readonly onMaxPerContact: (value: number) => void;
}): ReactElement {
  const nameId = useId();
  const descId = useId();
  const channelId_ = useId();
  const cooldownId = useId();
  const maxId = useId();

  const inputClass =
    "min-h-btn rounded-lg border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus:border-cog-blue-600 focus:outline-none focus:ring-2 focus:ring-cog-focus";

  return (
    <section className="flex flex-col gap-cog-4">
      <h2
        ref={headingRef}
        tabIndex={-1}
        className="text-heading-sm font-semibold text-cog-text-primary focus:outline-none"
      >
        {m.recipes_step_constraints()}
      </h2>
      <p className="text-caption text-cog-text-tertiary">
        {m.recipes_constraints_optional()}
      </p>

      {/* Channel scope */}
      <div className="flex flex-col gap-cog-1">
        <label
          htmlFor={channelId_}
          className="text-body-sm font-semibold text-cog-text-primary"
        >
          {m.recipes_constraints_channel()}
