  readonly state: WizardState;
  readonly selectedTrigger: TriggerTypeInfo | undefined;
  readonly selectedAction: ActionTypeInfo | undefined;
  readonly channels: ReadonlyArray<Option>;
  readonly groups: ReadonlyArray<Option>;
  readonly testing: boolean;
  readonly testResult: TestRecipeResponse | null;
  readonly testError: boolean;
  readonly saveError: boolean;
  readonly onTest: (sample: Record<string, unknown>) => void;
}): ReactElement {
