function SummaryRow({
  label,
  value,
  detail,
}: {
  readonly label: string;
  readonly value: string;
  readonly detail?: string;
}): ReactElement {
  return (
    <div className="flex flex-col gap-cog-0.5 sm:flex-row sm:gap-cog-2">
      <dt className="text-body-sm font-semibold text-cog-text-secondary sm:w-cog-14">
        {label}
      </dt>
      <dd className="text-body-sm text-cog-text-primary">
        <span>{value}</span>
        {detail ? (
          <span className="text-cog-text-secondary"> — {detail}</span>
        ) : null}
      </dd>
    </div>
  );
}

// Render "k: v, k: v" from a schema's config map for the read-back detail.
// Returns undefined when there are no fields/values, so the label stands alone.
function summarizeConfigDetail(
  fields: ReadonlyArray<ConfigField> | undefined,
  config: Record<string, unknown>,
): string | undefined {
  if (!fields || fields.length === 0) return undefined;
  const parts = fields
    .map((f) => {
      const v = config[f.name];
      if (v === undefined || v === null || v === "") return null;
      const printed = Array.isArray(v) ? v.join(", ") : String(v);
      if (printed === "") return null;
      return `${f.label}: ${printed}`;
    })
    .filter((p): p is string => p !== null);
  return parts.length > 0 ? parts.join(", ") : undefined;
}

// ─── Test panel ──────────────────────────────────────────────────────────────

function TestPanel({
  triggerType,
  triggerConfig,
  groups,
  testing,
  testResult,
  testError,
  onTest,
}: {
  readonly triggerType: string;
  readonly triggerConfig: Record<string, unknown>;
  readonly groups: ReadonlyArray<Option>;
  readonly testing: boolean;
  readonly testResult: TestRecipeResponse | null;
  readonly testError: boolean;
  readonly onTest: (sample: Record<string, unknown>) => void;
}): ReactElement {
  // The sample-trigger form is shaped by the trigger type.
  const [preview, setPreview] = useState<string>(() =>
    defaultPreview(triggerConfig),
  );
  const [isNew, setIsNew] = useState(true);
  const [groupId, setGroupId] = useState<string>(
    () => (typeof triggerConfig.group_id === "string"
      ? (triggerConfig.group_id as string)
      : ""),
  );

  const previewId = useId();
  const isNewId = useId();
  const groupSelId = useId();

  function buildSample(): Record<string, unknown> {
    if (triggerType === "conversation_started") return { is_new: isNew };
    if (triggerType === "contact_joined") return { group_id: groupId };
    // message_received / keyword_detected and any other text-shaped trigger.
    return { preview };
  }

  const usesPreview =
    triggerType === "message_received" || triggerType === "keyword_detected";

  const inputClass =
    "min-h-btn rounded-lg border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus:border-cog-blue-600 focus:outline-none focus:ring-2 focus:ring-cog-focus";

  return (
    <div className="flex flex-col gap-cog-3 rounded-lg border border-cog-border p-cog-4">
      {usesPreview && (
        <div className="flex flex-col gap-cog-1">
          <label
            htmlFor={previewId}
            className="text-body-sm font-semibold text-cog-text-primary"
          >
            {m.recipes_test_cta()}
          </label>
          <input
            id={previewId}
            type="text"
            value={preview}
            onChange={(e) => setPreview(e.target.value)}
            className={inputClass}
          />
        </div>
      )}
      {triggerType === "conversation_started" && (
        <span className="inline-flex items-center gap-cog-2">
          <input
            id={isNewId}
            type="checkbox"
            checked={isNew}
            onChange={(e) => setIsNew(e.target.checked)}
            className="h-cog-4 w-cog-4 text-cog-blue-600 focus:ring-2 focus:ring-cog-focus"
          />
          <label
            htmlFor={isNewId}
            className="text-body-sm text-cog-text-primary"
          >
            {m.recipes_test_cta()}
          </label>
        </span>
      )}
      {triggerType === "contact_joined" && (
        <div className="flex flex-col gap-cog-1">
          <label
            htmlFor={groupSelId}
            className="text-body-sm font-semibold text-cog-text-primary"
          >
            {m.recipes_field_group()}
          </label>
          <select
            id={groupSelId}
            value={groupId}
            onChange={(e) => setGroupId(e.target.value)}
            className={inputClass}
          >
            <option value="">{m.recipes_required()}</option>
            {groups.map((g) => (
              <option key={g.id} value={g.id}>
                {g.name}
              </option>
            ))}
          </select>
        </div>
      )}

      <div>
        <button
          type="button"
          onClick={() => onTest(buildSample())}
          disabled={testing}
          className="inline-flex min-h-btn items-center justify-center rounded-md border border-cog-border px-cog-4 py-cog-2 text-body-sm font-medium text-cog-text-primary hover:bg-cog-surface-subtle focus:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus disabled:cursor-not-allowed disabled:text-cog-text-tertiary"
        >
          {testing ? m.recipes_test_running() : m.recipes_test_cta()}
        </button>
      </div>

      {testError && (
        <p
          role="alert"
          className="text-body-sm text-cog-danger-600 dark:text-cog-danger-dark"
        >
          {m.recipes_create_error()}
        </p>
      )}

      {testResult && (
        <div role="status" className="flex flex-col gap-cog-2">
          <p className="text-body-sm font-semibold text-cog-text-primary">
            {testResult.trigger_matched ? (
              <Check aria-hidden="true" className="me-cog-1 inline-block h-cog-4 w-cog-4 align-text-bottom" />
            ) : (
              <X aria-hidden="true" className="me-cog-1 inline-block h-cog-4 w-cog-4 align-text-bottom" />
            )}
            {testResult.trigger_matched
              ? m.recipes_test_matched()
              : m.recipes_test_no_match()}
          </p>
          {testResult.match_detail !== "" && (
            <p className="text-caption text-cog-text-secondary">
              {testResult.match_detail}
            </p>
          )}
          {testResult.trigger_matched &&
            Object.keys(testResult.would_be_action).length > 0 && (
              <div className="flex flex-col gap-cog-0.5">
                <p className="text-caption font-semibold text-cog-text-secondary">
                  {m.recipes_test_would_do()}
                </p>
                {renderWouldBeAction(testResult.would_be_action).map((line) => (
                  <p
                    key={line}
                    className="text-body-sm text-cog-text-primary"
                  >
                    {line}
                  </p>
                ))}
              </div>
            )}
        </div>
      )}
    </div>
  );
}

// Default preview text: the first configured keyword, else a generic sample.
function defaultPreview(triggerConfig: Record<string, unknown>): string {
  const kws = triggerConfig.keywords;
  if (Array.isArray(kws) && kws.length > 0 && typeof kws[0] === "string") {
    return kws[0];
  }
  return "sample message";
}

// Flatten the would_be_action preview object into display lines. Known keys
// (rendered_body / priority / group_id) render bare; unknown keys fall back to
// "key: value" so a new server action never breaks the preview.
function renderWouldBeAction(action: Record<string, unknown>): string[] {
  const lines: string[] = [];
  for (const [key, val] of Object.entries(action)) {
    if (key === "rendered_body") lines.push(String(val));
    else lines.push(`${key}: ${String(val)}`);
  }
  return lines;
}


