// SchemaFields — renders a recipe trigger/action config schema as form fields.
//
// Each ConfigField is rendered according to its `type`:
//   string_list   → <KeywordChipsInput> (keyword pills)
//   enum:any|all  → a native radio group (Any of these / All of these)
//   uuid          → a native <select> populated from `groups` (group_id) or
//                   `channels` (channel / channel_id); placeholder option +
//                   disabled-with-hint when the relevant list is empty
//   int           → <input type="number" min="0">
//   bool          → a checkbox
//   text (+ any unknown) → <input type="text">
//
// Each field shows its server-provided `label` and optional `help` (wired via
// aria-describedby). Required fields carry a textual indicator. Fixed labels
// (match/keyword/org-wide hint) come from i18n; the dynamic per-field label is
// server-provided so this component carries no raw JSX literals.

import { type ReactElement, useId } from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import type { ConfigField } from "../../recipes/schema";
import { KeywordChipsInput } from "./KeywordChipsInput";

interface Option {
  readonly id: string;
  readonly name: string;
}

interface Props {
  readonly fields: ReadonlyArray<ConfigField>;
  readonly value: Record<string, unknown>;
  readonly onChange: (name: string, val: unknown) => void;
  readonly groups?: ReadonlyArray<Option>;
  readonly channels?: ReadonlyArray<Option>;
}

export function SchemaFields({
  fields,
  value,
  onChange,
  groups = [],
  channels = [],
}: Props): ReactElement {
  return (
    <div className="flex flex-col gap-cog-4">
      {fields.map((field) => (
        <FieldRenderer
          key={field.name}
          field={field}
          value={value[field.name]}
          onChange={onChange}
          groups={groups}
          channels={channels}
        />
      ))}
    </div>
  );
}

function FieldRenderer({
  field,
  value,
  onChange,
  groups,
  channels,
}: {
  readonly field: ConfigField;
  readonly value: unknown;
  readonly onChange: (name: string, val: unknown) => void;
  readonly groups: ReadonlyArray<Option>;
  readonly channels: ReadonlyArray<Option>;
}): ReactElement {
  const helpId = useId();
  const checkboxId = useId();
  const describedBy = field.help ? helpId : undefined;

  const help = field.help ? (
    <p id={helpId} className="text-caption text-cog-text-tertiary">
      {field.help}
    </p>
  ) : null;

  const requiredMark = field.required ? (
    <span className="ms-cog-0-5 text-caption text-cog-text-tertiary">
      ({m.recipes_required()})
    </span>
  ) : null;

  // string_list — keyword chip input owns its own label.
  if (field.type === "string_list") {
    const list = Array.isArray(value) ? (value as string[]) : [];
    return (
      <KeywordChipsInput
        value={list}
        onChange={(next) => onChange(field.name, next)}
        label={field.label || m.recipes_field_keywords()}
        help={field.help ?? m.recipes_field_keywords_help()}
      />
    );
  }

  // enum:any|all — radio group with the two fixed options.
  if (field.type === "enum:any|all") {
    const selected = typeof value === "string" ? value : "any";
    return (
      <fieldset className="flex flex-col gap-cog-1">
        <legend className="text-body-sm font-semibold text-cog-text-primary">
          {field.label || m.recipes_field_match()}
          {requiredMark}
        </legend>
        <div className="flex gap-cog-4" aria-describedby={describedBy}>
          <RadioOption
            name={field.name}
            optionValue="any"
            checked={selected === "any"}
            label={m.recipes_match_any()}
            onSelect={() => onChange(field.name, "any")}
          />
          <RadioOption
            name={field.name}
            optionValue="all"
            checked={selected === "all"}
            label={m.recipes_match_all()}
            onSelect={() => onChange(field.name, "all")}
          />
        </div>
        {help}
      </fieldset>
    );
  }

  // uuid — native select from groups or channels.
  if (field.type === "uuid") {
    const isChannel = field.name === "channel" || field.name === "channel_id";
    const options = isChannel ? channels : groups;
    const placeholder = isChannel ? m.recipes_org_wide() : m.recipes_required();
    const selected = typeof value === "string" ? value : "";
    const empty = options.length === 0;
    return (
      <FieldShell
        label={field.label}
        requiredMark={requiredMark}
        help={help}
        helpId={describedBy}
        control={(controlId) => (
          <select
            id={controlId}
            value={selected}
            disabled={empty}
            aria-describedby={describedBy}
            onChange={(e) => onChange(field.name, e.target.value)}
            className="min-h-btn rounded-lg border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus:border-cog-blue-600 focus:outline-none focus:ring-2 focus:ring-cog-focus disabled:cursor-not-allowed disabled:bg-cog-surface-subtle disabled:text-cog-text-tertiary"
          >
            <option value="">{placeholder}</option>
            {options.map((opt) => (
              <option key={opt.id} value={opt.id}>
                {opt.name}
              </option>
            ))}
          </select>
        )}
      />
    );
  }

  // int — number input.
  if (field.type === "int") {
    const num = typeof value === "number" ? value : 0;
    return (
      <FieldShell
        label={field.label}
        requiredMark={requiredMark}
        help={help}
        helpId={describedBy}
        control={(controlId) => (
          <input
            id={controlId}
            type="number"
            min="0"
            value={num}
            aria-describedby={describedBy}
            onChange={(e) => onChange(field.name, e.target.valueAsNumber || 0)}
            className="min-h-btn rounded-lg border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus:border-cog-blue-600 focus:outline-none focus:ring-2 focus:ring-cog-focus"
          />
        )}
      />
    );
  }

  // bool — checkbox. Falls back to `true` (the safe default) when unset,
  // matching schema.ts's defaultValueForType so a stale/missing value never
  // silently reads as "off".
  if (field.type === "bool") {
    const checked = typeof value === "boolean" ? value : true;
    return (
      <span className="inline-flex items-center gap-cog-2">
        <input
          id={checkboxId}
          type="checkbox"
          checked={checked}
          aria-describedby={describedBy}
          onChange={(e) => onChange(field.name, e.target.checked)}
          className="h-cog-4 w-cog-4 text-cog-blue-600 focus:ring-2 focus:ring-cog-focus"
        />
        <label htmlFor={checkboxId} className="text-body-sm text-cog-text-primary">
          {field.label}
          {requiredMark}
        </label>
        {help}
      </span>
    );
  }

  // text (+ any unknown type) — text input.
  const text = typeof value === "string" ? value : "";
  return (
    <FieldShell
      label={field.label}
      requiredMark={requiredMark}
      help={help}
      helpId={describedBy}
      control={(controlId) => (
        <input
          id={controlId}
          type="text"
          value={text}
          aria-describedby={describedBy}
          onChange={(e) => onChange(field.name, e.target.value)}
          className="min-h-btn rounded-lg border border-cog-border bg-cog-surface px-cog-3 text-body-sm text-cog-text-primary focus:border-cog-blue-600 focus:outline-none focus:ring-2 focus:ring-cog-focus"
        />
      )}
    />
  );
}

// FieldShell — shared label + control + help layout for the simple inputs.
function FieldShell({
  label,
  requiredMark,
  help,
  control,
}: {
  readonly label: string;
  readonly requiredMark: ReactElement | null;
  readonly help: ReactElement | null;
  readonly helpId: string | undefined;
  readonly control: (controlId: string) => ReactElement;
}): ReactElement {
  const controlId = useId();
  return (
    <div className="flex flex-col gap-cog-1">
      <label
        htmlFor={controlId}
        className="text-body-sm font-semibold text-cog-text-primary"
      >
        {label}
        {requiredMark}
      </label>
      {control(controlId)}
      {help}
    </div>
  );
}

// RadioOption — a single labelled native radio.
function RadioOption({
  name,
  optionValue,
  checked,
  label,
  onSelect,
}: {
  readonly name: string;
  readonly optionValue: string;
  readonly checked: boolean;
  readonly label: string;
  readonly onSelect: () => void;
}): ReactElement {
  const id = useId();
  return (
    <span className="inline-flex items-center gap-cog-1">
      <input
        id={id}
        type="radio"
        name={name}
        value={optionValue}
        checked={checked}
        onChange={onSelect}
        className="h-cog-4 w-cog-4 text-cog-blue-600 focus:ring-2 focus:ring-cog-focus"
      />
      <label htmlFor={id} className="text-body-sm text-cog-text-primary">
        {label}
      </label>
    </span>
  );
}



